const crypto = require('crypto');
const secret = ($env.AUTOMATION_WEBHOOK_SECRET || '').trim();
if (!secret) {
  throw new Error('AUTOMATION_WEBHOOK_SECRET environment variable is required.');
}

const frontendUrl = ($env.FRONTEND_PUBLIC_URL || 'http://host.docker.internal:3000').replace(/\/+$/, '');
const backendBase = ($env.BACKEND_API_BASE_URL || 'http://host.docker.internal:8000').replace(/\/+$/, '');

const probeEndpoint = async (url, expectOkJson = false) => {
  const started = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5000);
  try {
    const res = await fetch(url, { method: 'GET', signal: controller.signal });
    const latencyMs = Date.now() - started;
    if (!res.ok) {
      return { healthy: false, latencyMs, detail: `HTTP ${res.status}` };
    }
    if (expectOkJson) {
      const body = await res.json();
      const ok = body && body.status === 'ok';
      return { healthy: Boolean(ok), latencyMs, detail: ok ? 'status=ok' : 'status!=ok' };
    }
    return { healthy: true, latencyMs, detail: `HTTP ${res.status}` };
  } catch (err) {
    return { healthy: false, latencyMs: Date.now() - started, detail: String(err && err.message ? err.message : err) };
  } finally {
    clearTimeout(timer);
  }
};

const frontendProbe = await probeEndpoint(frontendUrl, false);
const backendProbe = await probeEndpoint(`${backendBase}/api/v1/health`, true);

const payload = {
  frontend_healthy: frontendProbe.healthy,
  backend_healthy: backendProbe.healthy,
  frontend_latency_ms: frontendProbe.latencyMs,
  backend_latency_ms: backendProbe.latencyMs,
  auto_clean: true
};

const rawBody = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');

return [{
  json: {
    rawBody,
    timestamp,
    signature,
    frontend_detail: frontendProbe.detail,
    backend_detail: backendProbe.detail
  }
}];

const result = $input.first().json;
const probeMeta = $('Probe Health & Sign Watchdog Payload').first().json;
const probeBody = JSON.parse(probeMeta.rawBody || '{}');

const deletedKeys = Array.isArray(result.deleted_chunk_keys) ? result.deleted_chunk_keys : [];
const keysSummary = deletedKeys.length
  ? deletedKeys.slice(0, 10).join(', ') + (deletedKeys.length > 10 ? ` (+${deletedKeys.length - 10} more)` : '')
  : 'None';

const discordPayload = {
  embeds: [
    {
      title: `[Portfolio Watchdog: ${String(result.status || 'degraded').toUpperCase()}]`,
      color: result.status === 'degraded' ? 15158332 : 15105570,
      fields: [
        {
          name: 'Frontend Health',
          value: `${result.frontend_healthy ? 'Healthy' : 'UNHEALTHY'} (${probeBody.frontend_latency_ms ?? 'n/a'}ms, ${probeMeta.frontend_detail || ''})`,
          inline: true
        },
        {
          name: 'Backend Health',
          value: `${result.backend_healthy ? 'Healthy' : 'UNHEALTHY'} (${probeBody.backend_latency_ms ?? 'n/a'}ms, ${probeMeta.backend_detail || ''})`,
          inline: true
        },
        {
          name: 'Stale Chunks Deleted',
          value: `${result.stale_chunks_deleted ?? 0} / ${result.stale_chunks_found ?? 0} found`,
          inline: true
        },
        {
          name: 'Deleted Chunk Keys',
          value: keysSummary.slice(0, 1000),
          inline: false
        },
        {
          name: 'Alert Reasons',
          value: (Array.isArray(result.alert_reasons) && result.alert_reasons.length ? result.alert_reasons.join('\n') : 'Watchdog alert triggered').slice(0, 1000),
          inline: false
        }
      ],
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: { discordPayload } }];
